import {accountsEnabled,refreshAccountHeader} from './account-header.js';
import {people} from '/socialite-data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const words={es:{explore:'Explorar',guides:'Guías',stays:'Alojamientos',socialite:'Socialité',happening:'Sucediendo ahora',skip:'Ir a las historias',checked:'Fuentes revisadas · 13 nov 2026',tagline:'Gente que deja huella.',edition:'ROMA · CONDESA',articles:'Artículos',profiles:'Referentes',profileIntro:'Trayectorias para conocer de cerca.',all:'Todo',gastronomia:'Gastronomía',arte:'Arte',letras:'Letras y periodismo',arquitectura:'Arquitectura',cine:'Cine',allZones:'Roma + Condesa',roma:'Roma',condesa:'Condesa',selected:'Selección editorial',newest:'Fecha de la fuente',az:'Nombre A–Z',saved:'Guardados',clear:'Limpiar filtros',source:'Fuente',original:'Leer artículo completo ↗',bio:'Biografía',career:'Trayectoria',connection:'Su vínculo con el barrio',related:'Para seguir leyendo',about:'Conoce su trayectoria ↗',seeProfile:'Ver perfil ↗',back:'Volver a Socialité',backProfiles:'Todos los referentes',archive:'Archivo',current:'Vínculo profesional',memory:'Memoria del barrio',read:'Leer historia',readTime:'Lectura breve',editorial:'Resumen original · La Vita',sourceDate:'Publicado por la fuente',noDate:'Fecha no indicada en la fuente',review:'Revisado por La Vita · 13 nov 2026',sources:'Fuentes y lectura completa',sourceNote:'Resumen editorial propio de La Vita, basado en la publicación citada.',rightsTitle:'Derechos del artículo original',rightsNote:'Todos los derechos del artículo original pertenecen a sus respectivos titulares.',selectionNote:'Selección editorial por trayectoria y vínculo documentado con el barrio. La inclusión no implica afiliación.',imageCredit:'Fotografía',photoEdit:'Recorte y tamaño adaptados',imageView:'Ver procedencia ↗',shared:'Enlace copiado.',share:'Copiar enlace',save:'Guardar artículo',unsave:'Quitar de guardados',savedToast:'Artículo guardado en esta sesión.',removedToast:'Artículo retirado de guardados.',search:'Busca una persona, historia o tema…',empty:'No hay historias con estos filtros.',emptyPeople:'No hay perfiles con estos filtros.',resultArticle:'artículo',resultProfile:'perfil',resultArticles:'artículos',resultProfiles:'perfiles',featured:'En portada',latest:'Más historias',allProfiles:'20 trayectorias · Roma y Condesa',sourceAuthor:'Autoría original',story:'Artículo relacionado',linked:'Vínculo documentado',of:'de',copyError:'Puedes copiar el enlace de la barra del navegador.'},en:{explore:'Explore',guides:'Guides',stays:'Stays',socialite:'Socialité',happening:'Happening now',skip:'Skip to stories',checked:'Sources checked · Nov 13, 2026',tagline:'People who leave a mark.',edition:'ROMA · CONDESA',articles:'Stories',profiles:'People to know',profileIntro:'Get to know the people behind the work.',all:'All',gastronomia:'Food & drink',arte:'Art',letras:'Writing & journalism',arquitectura:'Architecture',cine:'Film',allZones:'Roma + Condesa',roma:'Roma',condesa:'Condesa',selected:'Editor’s selection',newest:'Source publication date',az:'Name A–Z',saved:'Saved',clear:'Clear filters',source:'Source',original:'Read the full article ↗',bio:'Biography',career:'Career highlights',connection:'Their neighborhood connection',related:'Keep reading',about:'Explore their career ↗',seeProfile:'View profile ↗',back:'Back to Socialité',backProfiles:'All people',archive:'Archive',current:'Professional connection',memory:'Neighborhood memory',read:'Read story',readTime:'Short read',editorial:'Original summary · La Vita',sourceDate:'Published by the source',noDate:'No publication date provided',review:'Reviewed by La Vita · Nov 13, 2026',sources:'Sources & full story',sourceNote:'An original editorial summary by La Vita, based on the cited publication.',rightsTitle:'Original article rights',rightsNote:'All rights to the original article belong to their respective rights holders.',selectionNote:'An editorial selection based on careers and documented neighborhood connections. Inclusion does not imply affiliation.',imageCredit:'Photo',photoEdit:'Cropped and resized',imageView:'View image source ↗',shared:'Link copied.',share:'Copy link',save:'Save story',unsave:'Remove from saved',savedToast:'Story saved for this session.',removedToast:'Story removed from saved.',search:'Search a person, story or topic…',empty:'No stories match these filters.',emptyPeople:'No people match these filters.',resultArticle:'story',resultProfile:'profile',resultArticles:'stories',resultProfiles:'profiles',featured:'In focus',latest:'More stories',allProfiles:'20 careers · Roma and Condesa',sourceAuthor:'Original author',story:'Related story',linked:'Documented connection',of:'of',copyError:'You can copy the link from your browser’s address bar.'}};
let lang='es',tab=new URLSearchParams(location.search).get('seccion')==='referentes'?'profiles':'articles',category='all',zone='',q='',savedOnly=false,saved=new Set(),toastTimer;
try{lang=sessionStorage.getItem('lavita-language')==='en'?'en':'es';saved=new Set(JSON.parse(sessionStorage.getItem('lavita-social-saved')||'[]'));}catch{}
const t=k=>words[lang][k]||k,view=document.body.dataset.view,current=people.find(p=>p.id===document.body.dataset.person),url=(p,kind='article')=>'/socialite/'+(kind==='article'?'articulos':'referentes')+'/'+p.id,date=s=>s?new Intl.DateTimeFormat(lang==='es'?'es-MX':'en-US',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z')):t('noDate');
function img(p,cls='',eager=false){return `<img class="${cls}" style="object-position:${p.photo.position||'center 30%'}" src="/${p.photo.local}" alt="${esc(p.photo.caption)}" width="${p.photo.width}" height="${p.photo.height}" loading="${eager?'eager':'lazy'}" decoding="async">`;}
function sourceMeta(p){return `<span>${esc(p.source.name)}</span><span>${p.source.date?date(p.source.date):t('noDate')}</span>`;}
function label(p){return `<span class="social-category">${t(p.category)}</span><span>${t(p.zone)}</span>`;}
function saveButton(p){return `<button class="social-save" data-save="${p.id}" aria-pressed="${saved.has(p.id)}" aria-label="${t(saved.has(p.id)?'unsave':'save')} · ${esc(p.title[lang])}">${saved.has(p.id)?'◆':'◇'}</button>`;}
function storyCard(p){return `<article class="social-card">${saveButton(p)}<a class="social-card-link" href="${url(p)}"><div class="social-card-photo">${img(p)}${p.source.date&&p.source.date<'2026-01-01'?`<small class="social-archive">${t('archive')} · ${p.source.date.slice(0,4)}</small>`:''}</div><div class="social-label">${label(p)}</div><h3>${esc(p.title[lang])}</h3><p>${esc(p.bio[lang])}</p><div class="social-meta">${sourceMeta(p)}</div></a></article>`;}
function profileCard(p){return `<article class="social-person"><a href="${url(p,'profile')}"><div class="social-person-photo">${img(p)}</div><div class="social-label">${label(p)}</div><h3>${esc(p.name)}</h3><p>${esc(p.role[lang])}</p><small>${p.era==='memoria'?t('memory'):t('linked')} ↗</small></a></article>`;}
function feature(data){const [lead,...side]=data.slice(0,3);return `<section class="social-feature" aria-label="${t('featured')}"><article class="social-lead"><a href="${url(lead)}">${img(lead,'',true)}<div class="social-lead-shade"><div class="social-label">${label(lead)}</div><h2>${esc(lead.title[lang])}</h2><div class="social-meta">${sourceMeta(lead)}</div></div></a></article><div class="social-feature-side">${side.map(p=>`<article><a href="${url(p)}"><div>${img(p,'',true)}</div><section><div class="social-label">${label(p)}</div><h2>${esc(p.title[lang])}</h2><div class="social-meta">${sourceMeta(p)}</div></section></a></article>`).join('')}</div></section>`;}
function filtered(){let data=people.filter(p=>(category==='all'||p.category===category)&&(!zone||p.zone===zone||p.zones?.includes(zone))&&(!savedOnly||saved.has(p.id))&&(!q||norm(p.name+' '+p.title[lang]+' '+p.bio[lang]+' '+p.role[lang]+' '+p.connection[lang]+' '+t(p.category)+' '+p.source.name).includes(norm(q))));const sort=$('#social-sort')?.value||'selected';if(sort==='newest')data.sort((a,b)=>(b.source.date||'').localeCompare(a.source.date||''));if(sort==='az')data.sort((a,b)=>a.name.localeCompare(b.name));return data;}
function results(){const data=filtered(),featured=tab==='articles'&&category==='all'&&!zone&&!q&&!savedOnly&&($('#social-sort')?.value||'selected')==='selected';$('#social-results-count').textContent=`${data.length} ${t(tab==='articles'?(data.length===1?'resultArticle':'resultArticles'):(data.length===1?'resultProfile':'resultProfiles'))}`;$('#social-results').innerHTML=(featured?feature(data):'')+`<div class="social-section-head"><h2>${tab==='profiles'?t('profileIntro'):featured?t('latest'):t('articles')}</h2></div><div class="${tab==='articles'?'social-grid':'social-people-grid'}">${(featured?data.slice(3):data).map(tab==='articles'?storyCard:profileCard).join('')||`<div class="social-empty"><p>${t(tab==='articles'?'empty':'emptyPeople')}</p><button data-clear>${t('clear')}</button></div>`}</div>`;$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(category===b.dataset.category)));$$('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(tab===b.dataset.tab)));$('#social-saved').setAttribute('aria-pressed',String(savedOnly));$('#social-results').setAttribute('aria-labelledby','social-tab-'+tab);$$('[data-tab]').forEach(b=>b.tabIndex=b.dataset.tab===tab?0:-1);}
function home(){const sort=$('#social-sort')?.value||'selected';$('#social-content').innerHTML=`<div class="social-masthead"><div><h1>Socialité<span>✦</span></h1><p>${t('tagline')}</p></div><div class="social-edition"><span>${t('edition')}</span><small>${t('review')}</small></div></div><div class="social-topline"><div class="social-tabs" role="tablist" aria-label="Socialité"><button role="tab" id="social-tab-articles" aria-controls="social-results" data-tab="articles" aria-selected="${tab==='articles'}">${t('articles')}</button><button role="tab" id="social-tab-profiles" aria-controls="social-results" data-tab="profiles" aria-selected="${tab==='profiles'}">${t('profiles')} <small>20</small></button></div><button class="social-saved" id="social-saved" aria-pressed="${savedOnly}">◇ ${t('saved')} <small>${saved.size}</small></button></div><div class="social-tools"><div class="social-filters" aria-label="${t('all')}">${['all','gastronomia','arte','letras','arquitectura','cine'].map(c=>`<button data-category="${c}" aria-pressed="${category===c}">${t(c)}</button>`).join('')}</div><div class="social-tool-selects"><label><span class="sr-only">${t('allZones')}</span><select id="social-zone"><option value="">${t('allZones')}</option><option value="roma">Roma</option><option value="condesa">Condesa</option></select></label><label><span class="sr-only">${t('selected')}</span><select id="social-sort"><option value="selected">${t('selected')}</option><option value="newest">${t('newest')}</option><option value="az">${t('az')}</option></select></label><span id="social-results-count" role="status" aria-live="polite"></span></div></div><div id="social-results" role="tabpanel" aria-labelledby="social-tab-${tab}"></div><p class="social-selection-note">${t('selectionNote')}</p>`;$('#social-zone').value=zone;$('#social-sort').value=sort;$('#social-zone').onchange=e=>{zone=e.target.value;results();};$('#social-sort').onchange=results;$('#social-saved').onclick=()=>{savedOnly=!savedOnly;results();};results();}
function credits(p){return `<figcaption>${t('imageCredit')}: ${esc(p.photo.caption)} · ${esc(p.photo.credit||new URL(p.photo.source).hostname)} · <a href="${esc(p.photo.source)}" target="_blank" rel="noopener noreferrer">${t('imageView')}</a>${p.photo.licenseUrl?` · <a href="${esc(p.photo.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.photo.license)}</a> · ${t('photoEdit')}`:''}</figcaption>`;}
function sourceBlock(p){return `<aside class="social-source-block"><h2>${t('sources')}</h2><p><strong>${esc(p.source.name)}</strong> · ${p.source.date?`${t('sourceDate')}: ${date(p.source.date)}`:t('noDate')}${p.source.author?`<br>${t('sourceAuthor')}: ${esc(p.source.author)}`:''}</p><a class="social-source-title" href="${esc(p.source.url)}" target="_blank" rel="noopener noreferrer">${esc(p.source.title)} ↗</a><p>${t('sourceNote')}</p><a class="social-primary" href="${esc(p.source.url)}" target="_blank" rel="noopener noreferrer">${t('original')} · ${esc(p.source.name)}</a><p class="social-rights"><strong>${t('rightsTitle')}</strong><br>${t('rightsNote')}</p>${p.extraSources.length?`<div class="social-extra-sources">${p.extraSources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`).join('')}</div>`:''}<small>${t('review')}</small></aside>`;}
function related(p){const list=people.filter(x=>x.id!==p.id&&x.category===p.category).slice(0,3);return list.length?`<section class="social-related"><div class="social-section-head"><h2>${t('related')}</h2><a href="/socialite">${t('articles')} ↗</a></div><div class="social-grid">${list.map(storyCard).join('')}</div></section>`:'';}
function article(p){document.title=p.title[lang]+' · Socialité · La Vita';$('#social-content').innerHTML=`<nav class="social-breadcrumb"><a href="/socialite">← ${t('back')}</a><span>${t(p.category)}</span></nav><article class="social-article"><header class="social-article-header"><div class="social-label">${label(p)}</div><h1>${esc(p.title[lang])}</h1><p class="social-deck">${esc(p.bio[lang])}</p><div class="social-article-meta"><span>${t('editorial')}</span><span>${t('source')}: ${esc(p.source.name)} · ${date(p.source.date)}</span></div></header><figure class="social-article-figure">${img(p,'',true)}${credits(p)}</figure><div class="social-reading-layout"><div class="social-article-body"><p>${esc(p.body[lang])}</p><a class="social-profile-inline" href="${url(p,'profile')}">${img(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.role[lang])} · ${t('seeProfile')}</small></span><b>↗</b></a><div class="social-article-actions">${saveButton(p)}<button data-share>${t('share')} ↗</button><span>${t(saved.has(p.id)?'unsave':'save')}</span></div>${sourceBlock(p)}</div><aside class="social-context"><small>${t('connection')}</small><h2>${esc(p.name)}</h2><p>${esc(p.connection[lang])}</p><span>${t(p.era==='memoria'?'memory':'linked')}</span><a href="${url(p,'profile')}">${t('about')}</a></aside></div></article>${related(p)}`;}
function profile(p){document.title=p.name+' · Socialité · La Vita';$('#social-content').innerHTML=`<nav class="social-breadcrumb"><a href="/socialite?seccion=referentes">← ${t('backProfiles')}</a><span>${t('profiles')}</span></nav><article class="social-profile"><div class="social-profile-top"><figure>${img(p,'',true)}${credits(p)}</figure><div class="social-profile-intro"><div class="social-label">${label(p)}</div><h1>${esc(p.name)}</h1><p class="social-role">${esc(p.role[lang])}</p><p class="social-biography">${esc(p.bio[lang])}</p><div class="social-connection"><small>${t('connection')}</small><p>${esc(p.connection[lang])}</p><span>${t(p.era==='memoria'?'memory':'linked')}</span></div><button class="social-share" data-share>${t('share')} ↗</button></div></div><div class="social-profile-bottom"><section class="social-career"><h2>${t('career')}</h2><ol>${p.milestones.map(x=>`<li>${esc(x[lang])}</li>`).join('')}</ol><p class="social-career-source">${t('source')}: <a href="${esc(p.source.url)}" target="_blank" rel="noopener noreferrer">${esc(p.source.name)} ↗</a>${p.extraSources.map(s=>` · <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`).join('')}</p></section><section><h2>${t('story')}</h2>${storyCard(p)}</section></div><p class="social-selection-note">${t('selectionNote')}</p></article>${related(p)}`;}
function toast(text){clearTimeout(toastTimer);$('#social-toast').textContent=text;$('#social-toast').hidden=false;toastTimer=setTimeout(()=>$('#social-toast').hidden=true,3000);}
function render(){document.documentElement.lang=lang;$$('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));$('#language').value=lang;$('#social-search').placeholder=t('search');$('#social-search').setAttribute('aria-label',t('search'));if(view==='home'){document.title='Socialité · La Vita Roma Condesa';home();}else if(current){view==='article'?article(current):profile(current);}}
$('#social-search').oninput=e=>{q=e.target.value;if(view==='home')results();};if(view!=='home'){$('#social-search').value='';$('#social-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();location.href='/socialite?buscar='+encodeURIComponent(e.target.value);}};}
$('#language').onchange=e=>{lang=e.target.value;try{sessionStorage.setItem('lavita-language',lang);}catch{}render();};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-tab],[data-category],[data-clear],[data-save],[data-share]');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;history.replaceState(null,'','/socialite'+(tab==='profiles'?'?seccion=referentes':''));results();}if(b.dataset.category){category=b.dataset.category;results();}if(b.hasAttribute('data-clear')){category='all';zone='';q='';savedOnly=false;$('#social-search').value='';$('#social-zone').value='';results();}if(b.dataset.save){const id=b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{sessionStorage.setItem('lavita-social-saved',JSON.stringify([...saved]));}catch{}if(view==='home')home();else render();document.querySelector(`[data-save="${id}"]`)?.focus();toast(t(saved.has(id)?'savedToast':'removedToast'));}if(b.hasAttribute('data-share')){try{await navigator.clipboard.writeText(location.href);toast(t('shared'));}catch{toast(t('copyError'));}}});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();tab=e.key==='Home'?'articles':e.key==='End'?'profiles':tab==='articles'?'profiles':'articles';results();document.querySelector(`[data-tab="${tab}"]`)?.focus();});
$('#profile-button').onclick=()=>toast($('#profile-name').textContent+' · '+$('#profile-points').textContent+' · Demo');
if(accountsEnabled){refreshAccountHeader();}else{try{const profile=JSON.parse(sessionStorage.getItem('lavita-community-demo'));if(profile&&typeof profile.name==='string'&&Number.isFinite(profile.points)){$('#profile-name').textContent=profile.name;$('#profile-points').textContent=profile.points.toLocaleString()+' pts · Demo';$('.avatar').textContent=profile.name.slice(0,1);}}catch{}}
q=new URLSearchParams(location.search).get('buscar')||'';$('#social-search').value=q;render();
